#!/usr/bin/env node
// npm run email:disposable-update
//
// Refreshes src/server/auth/disposable-domains.data.ts from the community-maintained blocklist
// (https://github.com/disposable-email-domains/disposable-email-domains, public domain / CC0).
// Sign-up, email change and brand applications refuse these domains (src/server/auth/email-policy.ts).
// Run it now and then (monthly is plenty), review the diff, and commit the regenerated file.
// Domains Yard wants to allow anyway go in ALLOW below; extra ones to refuse go in
// email-policy.ts (EXTRA_BLOCKED), never in the generated file.
import { writeFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const SOURCE = "https://raw.githubusercontent.com/disposable-email-domains/disposable-email-domains/main/disposable_email_blocklist.conf"
/** Never refused, even if the upstream list names them. */
const ALLOW = new Set([])

const out = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../src/server/auth/disposable-domains.data.ts")
const res = await fetch(SOURCE, { signal: AbortSignal.timeout(30_000) })
if (!res.ok) {
  console.error(`Couldn't fetch the list: HTTP ${res.status}`)
  process.exit(1)
}
const domains = [...new Set((await res.text()).split("\n").map((l) => l.trim().toLowerCase()).filter((l) => l && !l.startsWith("#") && /^[a-z0-9.-]+\.[a-z0-9-]+$/.test(l) && !ALLOW.has(l)))].sort()
if (domains.length < 1000) {
  console.error(`Only ${domains.length} domains came back; refusing to overwrite the list.`)
  process.exit(1)
}
const body = `// GENERATED by scripts/update-disposable-domains.mjs from ${SOURCE}
// (${domains.length} domains, ${new Date().toISOString().slice(0, 10)}). Do not edit by hand: re-run the script.
export const DISPOSABLE_DOMAINS = \`
${domains.join("\n")}
\`
`
writeFileSync(out, body)
console.log(`Wrote ${domains.length} domains to ${path.relative(process.cwd(), out)}`)
